class Graph:
    def __init__(self, data=None):
        if data is None:
            data = []
        if not isinstance(data, (list, tuple)):
            raise TypeError("Graph data malformed")

        nodes = []
        edges = []
        attrs = {}

        for item in data:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                raise TypeError("Graph item incomplete")

            kind = item[0]
            if kind == ATTR:
                if (len(item) != 3 or
                        not isinstance(item[1], str) or
                        not isinstance(item[2], str)):
                    raise ValueError("Attribute is malformed")
                attrs[item[1]] = item[2]
            elif kind == NODE:
                if (len(item) != 3 or
                        not isinstance(item[1], str) or
                        not isinstance(item[2], dict)):
                    raise ValueError("Node is malformed")
                nodes.append(Node(item[1], item[2]))
            elif kind == EDGE:
                if len(item) == 3:
                    src, dst, edge_attrs = item[1], item[2], {}
                elif len(item) == 4:
                    src, dst, edge_attrs = item[1], item[2], item[3]
                else:
                    raise ValueError("Edge is malformed")
                if (not isinstance(src, str) or
                        not isinstance(dst, str) or
                        not isinstance(edge_attrs, dict)):
                    raise ValueError("Edge is malformed")
                edges.append(Edge(src, dst, edge_attrs))
            else:
                raise ValueError("Unknown item")

        self.nodes = nodes
        self.edges = edges
        self.attrs = attrs

